head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd   = ""; // 조회조건 기업코드

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 화면을 초기화한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00302.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name grd_AudtOpinSpeclablContn_oncelldblclick
 * @description 팝업 호출 — 감사의견 컬럼 더블클릭 시 감사의견 팝업, 특기사항 컬럼 더블클릭 시 특기사항 팝업을 오픈한다.
 * @param {Number} rowIndex 더블클릭한 행 인덱스
 * @param {Number} columnIndex 더블클릭한 컬럼 인덱스
 * @param {String} columnId 더블클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_AudtOpinSpeclablContn_oncelldblclick(0, 0, "audtOpinNm");
 */
scwin.grd_AudtOpinSpeclablContn_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {

        if (columnId === "audtOpinNm") {
            if (dlt_AudtOpinSpeclablContnRes.getCellData(rowIndex, "audtOpinYn") === "1") {
                // 감사의견  팝업 오픈
                scwin.audtOpinSrchOpen(rowIndex);
            }
        } else if (columnId === "ctnt") {
            // 특기사항 팝업 오픈
            scwin.speclablContnSrchOpen(rowIndex);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00302.grd_AudtOpinSpeclablContn_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {
    scwin.search();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_AudtOpinSpeclablContnRes.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 유효성 체크 결과
 * @hidden N
 * @example if (!scwin.chkValid()) { return; }
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd=== "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 감사의견및특기사항 조회
 * @returns {void}
 * @hidden N
 * @example await scwin.search();
 */
scwin.search = async function()  {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // const ibxCoSnm = $p.parent().wfm_header.getWindow().ibx_CoSnm.getValue();
    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    // const ibxCoSnm = "제일교통(주)"
    // const ibxKisCd = "803782";

    const url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/audit-opinion";
    $c.sbm.setAction(sbm_dlt_AudtOpinSpeclablContn, url);
    await $c.sbm.execute(sbm_dlt_AudtOpinSpeclablContn);

};

/**
 * @method
 * @name audtOpinSrchOpen
 * @description 감사의견 검색 팝업
 * @param {Number} pRow 대상 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.audtOpinSrchOpen(0);
 */
scwin.audtOpinSrchOpen = function(pRow)  {
    console.log(pRow);
    const url = "/ui/lst/fis/ULDFIS00300_P1.xml";
    const popTitle = "감사의견 검색";

    const opts = {
        id: "ULDFIS00300_P1",
        popupName: popTitle,
        width: 700,
        height: 590,
        frameModal: "top",
    };

    const popData = dlt_AudtOpinSpeclablContnRes.getRowJSON(pRow);
    console.log("rowData :: "  + popData);
    $c.win.openPopup(url, opts, popData);

};

/**
 * @method
 * @name speclablContnSrchOpen
 * @description 특기사항 팝업
 * @param {Number} pRow 대상 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.speclablContnSrchOpen(0);
 */
scwin.speclablContnSrchOpen = function(pRow) {
    // 적정인경우 스킵
    if (dlt_AudtOpinSpeclablContnRes.getCellData(pRow, "ctnt") !== "more") {
        return;
    }

    const url = "/ui/lst/fis/ULDFIS00300_P2.xml";
    const popTitle = "특기사항 검색";

    const opts = {
        id: "ULDFIS00300_P2",
        popupName: popTitle,
        width: 900,
        height: 590,
        frameModal: "top",
    };

    const popData = dlt_AudtOpinSpeclablContnRes.getRowJSON(pRow);
    $c.win.openPopup(url, opts, popData);
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 * @example scwin.excelDownload();
 */
scwin.excelDownload = function() {

    if (dlt_AudtOpinSpeclablContnRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_AudtOpinSpeclablContn, {fileName: "감사의견및특기사항", type: "8"});
};

/**
 * @method
 * @name setStyleExp
 * @description 스타일 제어 — 감사의견/특기사항 셀에 밑줄 스타일을 적용한다(그리드 customFormatter).
 * @param {Object} data 셀 원본 값
 * @param {Object} formattedData 포맷 적용 값
 * @param {Number} rowIdx 행 인덱스
 * @param {Number} colIdx 컬럼 인덱스
 * @returns {Object} 셀 원본 값(data) 그대로 반환
 * @hidden N
 * @example (grd_AudtOpinSpeclablContn 컬럼 customFormatter 바인딩으로 자동 호출)
 */
scwin.setStyleExp = function (data, formattedData, rowIdx, colIdx) {
    const audtOpinYn = dlt_AudtOpinSpeclablContnRes.getCellData(rowIdx, "audtOpinYn");
    const ctnt = dlt_AudtOpinSpeclablContnRes.getCellData(rowIdx, "ctnt");

    if (audtOpinYn === "1") {
        grd_AudtOpinSpeclablContn.setCellStyle(rowIdx, "audtOpinNm", "text-decoration", "underline");
    }
    if(ctnt === "more") {
        grd_AudtOpinSpeclablContn.setCellStyle(rowIdx, "ctnt", "text-decoration", "underline");
    }
    return data;
};
